SELECT UTC_TIMESTAMP(3) observed_utc;
SELECT lifecycle,COUNT(*) n,MIN(FROM_UNIXTIME(created_at/1000)) oldest_created_utc,MAX(TIMESTAMPDIFF(SECOND,FROM_UNIXTIME(updated_at/1000),UTC_TIMESTAMP())) max_unchanged_seconds FROM account_creator_deletion GROUP BY lifecycle;
SELECT status,deletion_result_status,COUNT(*) n,MIN(FROM_UNIXTIME(created_at/1000)) oldest_created_utc FROM pull_task_creator_deletion GROUP BY status,deletion_result_status;
SELECT d.account_id,d.tenant_id,d.task_id,d.group_execution_id,d.lifecycle,d.operation_id IS NOT NULL has_operation,FROM_UNIXTIME(d.created_at/1000) reserved_utc,FROM_UNIXTIME(d.updated_at/1000) updated_utc,TIMESTAMPDIFF(SECOND,FROM_UNIXTIME(d.created_at/1000),UTC_TIMESTAMP()) age_seconds,a.deleted_at IS NOT NULL platform_deleted,a.account_group_id,a.protocol_id,s.account_state,s.login_state,s.desired_login_state,s.state_source,a.dispatched_at IS NOT NULL dispatched,a.lease_until,t.status task_status,t.deleted_at IS NOT NULL task_deleted,e.execution_status,e.stage,e.create_step,e.reason_code,e.lock_owner IS NOT NULL execution_locked,e.lock_expires_at,p.status deletion_status,p.attempts,p.deletion_result_status,p.reason_code deletion_reason,FROM_UNIXTIME(p.submitted_at/1000) submitted_utc FROM account_creator_deletion d LEFT JOIN account a ON a.id=d.account_id LEFT JOIN account_state s ON s.account_id=a.id AND s.tenant_id=a.tenant_id LEFT JOIN pull_task t ON t.id=d.task_id AND t.tenant_id=d.tenant_id LEFT JOIN pull_task_group_execution e ON e.id=d.group_execution_id AND e.tenant_id=d.tenant_id LEFT JOIN pull_task_creator_deletion p ON p.tenant_id=d.tenant_id AND p.group_execution_id=d.group_execution_id;
SELECT a.id,a.deleted_at IS NOT NULL platform_deleted,a.protocol_id,a.device_os,a.account_group_id,a.dispatched_at IS NOT NULL dispatched,a.lease_until,s.account_state,s.login_state,s.desired_login_state,s.state_source,d.lifecycle,d.task_id,d.group_execution_id FROM account a LEFT JOIN account_state s ON s.account_id=a.id AND s.tenant_id=a.tenant_id LEFT JOIN account_creator_deletion d ON d.account_id=a.id WHERE a.id IN (1038,1736,2755,2757);
SELECT t.id,t.status,t.primary_stage,t.blocking_reason,t.deleted_at IS NOT NULL deleted,t.is_creator_delete_after_takeover,FROM_UNIXTIME(t.finished_at/1000) finished_utc,e.id execution_id,e.execution_status,e.stage,e.create_step,e.reason_code,e.lock_owner IS NOT NULL locked,FROM_UNIXTIME(e.lock_expires_at/1000) lock_expires_utc FROM pull_task t LEFT JOIN pull_task_group_execution e ON e.task_id=t.id AND e.tenant_id=t.tenant_id WHERE t.id IN (64,65);
SELECT d.lifecycle,COUNT(DISTINCT a.id) aliases,SUM(a.deleted_at IS NULL) active_aliases,COUNT(DISTINCT a.tenant_id) tenants,COUNT(DISTINCT d.task_id) tasks FROM account_creator_deletion d JOIN account a ON d.account_id=a.id OR d.creator_phone=a.creator_deletion_identity_phone GROUP BY d.lifecycle;
SELECT a.id,d.account_id reserved_account_id,d.lifecycle,a.protocol_id,a.deleted_at IS NOT NULL platform_deleted FROM account_creator_deletion d JOIN account a ON d.account_id=a.id OR d.creator_phone=a.creator_deletion_identity_phone ORDER BY d.account_id,a.id;
SELECT o.status,o.command_type,COUNT(*) n,MIN(FROM_UNIXTIME(o.created_at/1000)) oldest_utc FROM protocol_command_outbox o WHERE o.deleted_at IS NULL AND o.status IN (0,1,5,6) AND EXISTS (SELECT 1 FROM account a WHERE a.protocol_account_id=o.protocol_account_id AND (a.id IN (1038,1736,2755,2757) OR EXISTS (SELECT 1 FROM account_creator_deletion d WHERE d.account_id=a.id OR d.creator_phone=a.creator_deletion_identity_phone))) GROUP BY o.status,o.command_type;
SELECT table_name,column_name,data_type FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name IN ('pull_task_group_account','account_credential','account_proxy_binding','account_group_relation','group_member','group_account_relation','protocol_command_result','account_online_attempt_log','marketing_account_occupancy','feed_task_account','contact_friend_task_account') ORDER BY table_name,ordinal_position;
